import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

const ICON_192 = "";
const ICON_512 = "";
const MANIFEST = {
  name: "Popote", short_name: "Popote", description: "Recettes adaptées à ton budget, tes appareils, tes allergies et tes protéines",
  start_url: "/", scope: "/", display: "standalone", background_color: "#F7F5EF",
  theme_color: "#F7F5EF", orientation: "portrait",
  icons: [
    { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
    { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
    { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }
  ]
};
const SW = `const CACHE="popote-cache-v2";
self.addEventListener("install",()=>self.skipWaiting());
self.addEventListener("activate",(e)=>{e.waitUntil(caches.keys().then((ks)=>Promise.all(ks.filter((k)=>k!==CACHE).map((k)=>caches.delete(k)))));self.clients.claim();});
self.addEventListener("fetch",(e)=>{if(e.request.method!=="GET")return;e.respondWith(caches.open(CACHE).then(async(c)=>{const hit=await c.match(e.request);const net=fetch(e.request).then((r)=>{if(r.ok)c.put(e.request,r.clone());return r;}).catch(()=>hit);return hit||net;}));});`;

function pwaAssets() {
  return { name: "pwa-assets", generateBundle() {
    this.emitFile({ type: "asset", fileName: "manifest.json", source: JSON.stringify(MANIFEST) });
    this.emitFile({ type: "asset", fileName: "sw.js", source: SW });
    this.emitFile({ type: "asset", fileName: "icon-192.png", source: Buffer.from(ICON_192, "base64") });
    this.emitFile({ type: "asset", fileName: "icon-512.png", source: Buffer.from(ICON_512, "base64") });
  }};
}
export default defineConfig({ plugins: [react(), pwaAssets()] });
